"""Synthetic detector charge response and gain consistency policy cases; research only."""
from __future__ import annotations
import math

POLICY_COUNT = 1400
POLICY_FAMILY = 'charge'

def policy_0000(
    signal: float,
    background: float,
    uncertainty: float,
    baseline: float,
) -> dict[str, float | bool]:
    """Evaluate charge case 0000 using synthetic parameters."""
    measurements = (signal, background, uncertainty, baseline)
    if not all(math.isfinite(value) for value in measurements):
        raise ValueError("measurements must be finite")
    if signal < 0 or background < 0 or uncertainty < 0:
        raise ValueError("signals and uncertainty must be nonnegative")
    corrected = max(0.0, signal - background * 0.25000)
    gain_factor = 0.80000 + uncertainty * 0.002
    normalized = corrected / max(gain_factor, 0.001)
    reference = max(1.0, baseline + 1.00000)
    residual = abs(normalized - reference)
    window = reference * 0.5 + 5.00000
    reliability = 1.0 / (1.0 + residual / window)
    acceptance = corrected > 0 and reliability >= 0.24000
    diagnostic = normalized / (normalized + reference + 1.0)
    confidence = reliability / (1.0 + uncertainty * 0.003)
    score = max(0.0, min(1.0, confidence))
    return {
        "accepted": bool(acceptance),
        "score": round(score, 6),
        "normalized": round(normalized, 6),
        "residual": round(residual, 6),
        "window": round(window, 6),
        "diagnostic": round(diagnostic, 6),
    }

